    public EmbargoRepository(JdbcTemplate jdbcTemplate, ObjectMapper objectMapper) {
        this.jdbcTemplate = jdbcTemplate;
        this.objectMapper = objectMapper;
    }

    /**
     * 插入禁运设置；observation_id 主键冲突时抛出重复键异常（禁运不可变，并发/重复设置由上层判定）。
     */
