public EmbargoOutcome setEmbargoBatch(SetEmbargoRequest request) {
    List<EmbargoItemRequest> items = normalizeAndSort(request.items());
    String fingerprint = fingerprint("EMBARGO", request.operator(), canonicalItemsJson(items));
    EmbargoOutcome replayed = checkEmbargoReplay(request.requestId(), fingerprint);
    if (replayed != null) return replayed;
    EmbargoOutcome concurrent = insertEmbargoPlaceholder(request.requestId(), fingerprint);
    if (concurrent != null) return concurrent;

