void unresolvedConflictBlocksEmbargoUntilResolved() throws Exception {
    create("req-c1", "obs-1", "站点A", "1.0", "备注").andExpect(status().isCreated());
    merge("req-m1", "obs-1", 1, "站点B", "1.0", "备注").andExpect(status().isOk());
